func addMigrationStateFieldPatches(patchSet *patch.PatchSet, origMS *virtv1.VirtualMachineInstanceMigrationState, newMS *virtv1.VirtualMachineInstanceMigrationState) {
	if newMS == nil {
		patchSet.AddOption(
			patch.WithTest("/status/migrationState", origMS),
			patch.WithRemove("/status/migrationState"),
		)
		return
	}
	if origMS == nil {
		origMS = &virtv1.VirtualMachineInstanceMigrationState{}
	}

	origValue := reflect.ValueOf(*origMS)
	newValue := reflect.ValueOf(*newMS)
	stateType := origValue.Type()

	for i := 0; i < stateType.NumField(); i++ {
		jsonTag := strings.Split(stateType.Field(i).Tag.Get("json"), ",")[0]
		if jsonTag == "" || jsonTag == "-" {
			continue
		}

		origField := origValue.Field(i)
		newField := newValue.Field(i)
		if apiequality.Semantic.DeepEqual(origField.Interface(), newField.Interface()) {
			// Unchanged field, nothing to patch.
			continue
		}

		path := "/status/migrationState/" + jsonTag
		if origField.IsZero() {
			// Field went from zero to non-zero, add it.
			patchSet.AddOption(patch.WithAdd(path, newField.Interface()))
		} else if !newField.IsZero() {
			// Field is non-zero in both but differs, test then replace it.
			patchSet.AddOption(
				patch.WithTest(path, origField.Interface()),
				patch.WithReplace(path, newField.Interface()),
			)
		}
	}
}

